import type { Role } from "@/lib/types";

export type TokenAction = "list" | "create" | "delete";

export interface TokenRuleInput {
  action: TokenAction;
  role: string;
}

export interface TokenRuleDecision {
  allowed: boolean;
  reason?: string;
}

/** Role → allowed actions matrix. Extend as needed. */
const ALLOWED: Record<TokenAction, Role[]> = {
  list:   ["sysadmin", "admin"],
  create: ["sysadmin", "admin"],
  delete: ["sysadmin"],
};

export function applyTokenRules(input: TokenRuleInput): TokenRuleDecision {
  const allowed = ALLOWED[input.action].includes(input.role as Role);
  return allowed
    ? { allowed: true }
    : { allowed: false, reason: `role ${input.role} cannot ${input.action}` };
}
